/** Preserve stable IDs while replacing obsolete broad claims at the final catalog layer. */
export function applyMcpCompleteGuideOverlay(input: PageInput): PageInput {
  const affected = new Set(["connections", "mcp-connections", "mcp-registration", "mcp-authentication", "bot-settings-mcp", "skills", "bot-settings-skills", "owner-pairing-offer", "approval-modes"]);
  if (!affected.has(input.id)) return input;
  const generic = "Quando houver workflow de setup correlacionado, o humano pode concluir Permitir e continuar após conta/grants/pins confirmados; o host cria uma continuação única da tarefa original. Sem esse workflow, novos grants só entram na próxima lease; nunca invente mensagem ok, autorização ou relist da engine.";
  const revise = (value: string): string => value.replaceAll("Ferramentas novas só chegam ao próximo turno.", generic).replaceAll("Novas tools próximo turno.", generic)
    .replaceAll("novas ferramentas só próximo turno.", generic).replaceAll("disponível no próximo turno.", "disponível numa lease nova ou continuação de setup confirmada, conforme os gates reais.")
    .replaceAll("nenhuma ferramenta chega ao turno atual ou a outros bots.", "nenhuma seleção é aplicada antes da decisão. O diretório mantém os alvos admitidos na abertura da lease, removendo revogados; novos grants exigem nova lease ou continuação de setup, sem acesso a pares.")
    .replaceAll("Ferramentas novas valem a partir da próxima resposta; snapshot relido na seção.", generic)
    .replaceAll("Não há ferramenta do bot para conectar contas, mudar acesso ou desconectar;", "connections.request pode propor setup próprio com aprovação exata; não autentica, muda acesso ou desconecta;");
  const notes = input.id === "connections" ? [...input.notes.map(revise), ...workflowNotes] : [...input.notes.map(revise), authority, pairedMcp, generic];
  const fields = input.fields.map(value => {
    const revised = { ...value, read: revise(value.read), change: revise(value.change), approval: revise(value.approval), result: revise(value.result), recovery: revise(value.recovery) };
    if (input.id === "bot-settings-mcp" && value.id === "bot-settings.mcp.global") return { ...revised,
      change: "Abre o gerenciador nativo Conexões MCP (McpConnectionsView) na mesma base e bot desta janela. A galeria unificada fica em Ajustes › Conexões. Cadastro, login e discovery mantêm seus fluxos privados. Fechar/Voltar/Escape são navegação, sem repetir intenções.",
      result: "Apresentação da base/bot corretos; ao fechar relê a seleção sem POST. Disponibilidade remota depende dos escopos explícitos e da interface realmente composta." };
    if (input.id !== "connections" || value.id.startsWith("connections.platform-configuration") || value.id.startsWith("connections.platform-credential")) return revised;
    const authPrivate = value.id.startsWith("connections.authorization") || value.id === "connections.connect";
    return { ...revised, scope: `${value.scope}; canal owner ou pareado com ${authPrivate ? "connections.manage" : value.changeOperation ? "connections.manage (mutação) / connections.read (consulta)" : "connections.read"} explícito`,
      ...(value.id === "connections.account.bot-access" ? { change: `${revised.change} toolNames?:lista sem duplicatas de até32 nomes revisados da conta seleciona operações exatas. Quando ausente, o contrato aplica o conjunto atual revisado; não inclui novas ferramentas silenciosamente. Mesmo clientRequestId/corpo/revisão para reconciliação.` } : {}),
      ...(value.id === "connections.account.bot-access" ? { recovery: `${revised.recovery} GET receipt resolve accessOutcome not_applied quando o Hub não fez commit e não há escrita em voo; superseded quando receipt existe mas conta/grants mudaram. Ambos encerram a pendência, sem replay de grant; releia estado e só um novo gesto/revisão cria outro pedido. Ausência do campo em receipt histórico significa aplicado.` } : {}),
      ...(value.id === "connections.connect" ? { change: `${revised.change} setupRequestId? correlaciona a autorização com o pedido de setup original; não concede grant nem agenda continuação por login isolado.` } : {}),
      approval: `${pairedConnections} O bot pode propor somente connections.request, com aprovação exact_owner; não opera o login, altera grants ou desconecta sozinho.`,
      readOperation: value.readOperation?.replace("owner-local", authPrivate ? "owner ou pareado connections.manage" : "owner ou pareado connections.read") ?? null,
      changeOperation: value.changeOperation?.replace("owner-local", "owner ou pareado connections.manage") ?? null };
  });
  const byId=new Map(fields.map(value=>[value.id,value]));
  for(const value of uiFields[input.id]??[])byId.set(value.id,value);
  return { ...input, sourcePaths: [...new Set([...input.sourcePaths,...sourcePaths])], notes, fields:[...byId.values()] };
}
